const art = (n, seccion, titulo, resumen, extra = {}) => ({
  id: n,
  titulo,
  slug: titulo.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''),
  resumen,
  contenido: resumen,
  seccion,
  firma: 'Redacción',
  autor_id: id(1),
  estado: 'publicado',
  nota_revision: null,
  uso_ia: 'ninguno',
  imagen_url: null,
  imagen_ia: false,
  medio: null,
  enlace_externo: null,
  revisado_por: id(1),
  publicado_at: hace(n * 3),
  creado_at: hace(n * 3 + 1),
  actualizado_at: hace(n * 3),
  ...extra,
})

